functions.getGridWidth:
function getGridWidth() {
		try {
			var w = window.parent.$("#screensWrapper").width();
			if(w>100)
				return window.parent.$("#screensWrapper").width()-10;
			else
				return $(window).width()-10;
		} catch (e) {
			console.log(e.message);
			return $(window).width()-10;
		}
	}

functions.shortcutKey:
function shortcutKey(){ 		
    	$(document).bind('keydown', function(e) {
    		var keyCode = (e.keyCode) ? e.keyCode : ((e.charCode) ? e.charCode : e.which);
    		if (e.originalEvent.altKey) {
    			// ALT + S     Search                   
    			if (keyCode === 83) {
    				reloadSearchGrid();
    				e.preventDefault();
    				return false;

    			}
    			// ALT + N      Reset                 
    			if (keyCode == 78) {
    				resetAll();
    				e.preventDefault();
    				return false;
    			}
    			// ALT + F    Add New
    			if (keyCode == 70){
    				addnew();
    				e.preventDefault();
    				return false;
    			}

    		}
    	});
    }

functions.deleteApiName:
function deleteApiName(event, apiId, seqId){
			var rowCount = $("#apiNameTable").getGridParam("reccount");
			if(rowCount == 1){
				window.parent.showAlert("Unable to delele Last Api Name");
				return false;
			}

			if (confirm("Do You Want To Delete this API Name?")) {

				var retVal = $.ajax({
					url : "deleteApiName",

					type : "POST",
					data : {
						apiId	: apiId,
						seqId	: seqId
					},
					dataType : "json",
					async : false
				}).responseText;

				retVal = jQuery.parseJSON(retVal);
				if(retVal.jsonMessage != null)
					window.parent.showAlert(retVal.jsonMessage);	
				jQuery("#apiNameTable").trigger('reloadGrid');
			}
			return false;
		}

