functions.genricSearchGridResized:
function genricSearchGridResized() {
			var gridObj = $("#apiNameTable");
			var extraHeight = ($("#fileNameValue").length > 0) ? 35 : 0;
			var height = ("Y" == ''|| "y" == '') ? 410 : 380;
			var gridHeight = window.parent.getParentHeight()-height-extraHeight;//VE-8908//VE-45573 SE

			var gridWidth = $(window).width()-15;
			if(gridWidth<270)
				gridWidth=270;
			gridObj.jqGrid('setGridWidth',gridWidth);		

			$("#gbox_"+gridObj[0].id+" .ui-jqgrid-bdiv").css("height",gridHeight+"px").css('overflow-x',($(window).width()<992 ?'auto':'hidden'));
			oldWidth=gridWidth;
		}

functions.checkIPAddressLength:
function checkIPAddressLength(alloweIPs) {
			var alloweIPs = $("#allowedIPs").val();
			if (alloweIPs !=null && alloweIPs !="") {
				var ipVal=alloweIPs.split(",");
				if(ipVal.length >200) {
					window.parent.showAlert("A maximum 200 IPs are allowed");
					return false;
				}
				if (!validateIPAddress(alloweIPs, errMsg)) {
					return false;
				}
			}
			return true;
		}

